module lumax_cycle_probe(
 input logic clock, reset,
 input logic [2:0] state,
 input logic afire, rawd, deliver,
 input logic [63:0] address,
 input logic [2:0] opcode,
 input int unsigned source, response_source,
 input int unsigned blocks, column, produced, kcount, rows, wb,
 input logic full0, full1, readon, done, done_acc, delayflag
);
 integer fd=0;
 string filename;
 longint unsigned ticks=0;
 integer previous_state=0, operation=-1;
 initial begin
  if ($value$plusargs("lumax_cycle_trace=%s", filename)) fd=$fopen(filename,"w");
 end
 always @(posedge clock) begin
  if (reset) begin ticks=0;previous_state=0;operation=-1;end
  else begin
   ticks=ticks+1;
   if (state==1 && previous_state==0) operation=operation+1;
   if (fd!=0) begin
    if (state!=previous_state) $fwrite(fd,"S %0d %0d %0d %0d %0d %0d %0d\n",operation,ticks,state,blocks,rows,wb,column);
    if (state>=1 && state<=4) $fwrite(fd,"T %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %0d\n",operation,ticks,state,blocks,column,produced,kcount,full0,full1,readon,done,done_acc,delayflag);
    if (afire) $fwrite(fd,"A %0d %0d %0d %0d %h %0d\n",operation,ticks,state,source,address,opcode);
    if (rawd) $fwrite(fd,"R %0d %0d %0d\n",operation,ticks,response_source);
    if (deliver) $fwrite(fd,"D %0d %0d %0d\n",operation,ticks,state);
   end
   previous_state=state;
  end
 end
 final begin if(fd!=0)$fclose(fd);end
endmodule

bind LUMAXExample lumax_cycle_probe cycle_probe(
 .clock(clock),.reset(reset),.state(state),
 .afire(auto_tl_out_a_valid && auto_tl_out_a_ready),
 .rawd(auto_tl_out_d_valid),.deliver(_dma_io_d_valid),
 .address(auto_tl_out_a_bits_address),.opcode(auto_tl_out_a_bits_opcode),
 .source(int'(auto_tl_out_a_bits_source)),.response_source(int'(auto_tl_out_d_bits_source)),
 .blocks(int'(blocks_in_Sync_mem)),.column(int'(w_idx)),.produced(int'(w_count)),
 .kcount(int'(counter_2)),.rows(int'(YS)),.wb(int'(weight_bits)),
 .full0(buffers_mode_0),.full1(buffers_mode_1),.readon(READ_ON),
 .done(Done),.done_acc(Done_acc),.delayflag(delay)
);
